input.content:
:root {
  --ink: #071c23;
  --ink-2: #0a2830;
  --panel: rgba(6, 26, 31, 0.74);
  --panel-solid: #0a2229;
  --line: rgba(226, 240, 224, 0.16);
  --line-strong: rgba(226, 240, 224, 0.3);
  --sand: #f2d79b;
  --sand-soft: #e8c98a;
  --gold: #f0b35a;
  --teal: #54dbc4;
  --coral: #ff6f5e;
  --green: #a7e36b;
  --text: #eef4e8;
  --muted: #a9bdb5;
  --shadow: 0 18px 50px rgba(0, 0, 0, 0.4);
  --font: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
  --font-narrow: "Arial Narrow", "Roboto Condensed", "Trebuchet MS", sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--text);
  font-family: var(--font);
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body { position: fixed; inset: 0; }

button { font-family: inherit; cursor: pointer; }
canvas { display: block; }

#app { position: fixed; inset: 0; }

#scene {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  outline: none;
  touch-action: none;
}

.hidden { display: none !important; }

/* ------------------------------------------------------------------ FX */
#fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 5;
}

#stormTint, #waterTint, #damageTint, #flashTint {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity 0.5s ease;
}
#stormTint {
  background:
    radial-gradient(circle at 50% 20%, rgba(84, 108, 118, 0.08), rgba(9, 24, 31, 0.62) 82%),
    linear-gradient(180deg, rgba(41, 59, 68, 0.28), rgba(4, 14, 19, 0.4));
}
#waterTint {
  background: radial-gradient(circle at 50% 50%, rgba(10, 92, 104, 0.08), rgba(4, 43, 54, 0.55) 90%);
}
#damageTint {
  background: radial-gradient(circle at 50% 50%, transparent 30%, rgba(138, 17, 17, 0.66) 100%);
  transition: opacity 0.35s ease;
}
#flashTint { background: rgba(220, 235, 255, 0.9); transition: opacity 0.08s ease; }
#vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 50% 46%, transparent 52%, rgba(2, 10, 13, 0.46) 100%);
}

/* ------------------------------------------------------------------ HUD */
#hud {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  font-size: 13px;
}

.hud-left {
  position: absolute;
  top: calc(16px + env(safe-area-inset-top));
  left: calc(16px + env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
}

.brand {
  display: flex;
  align-items: center;
  gap: 7px;
  font-family: var(--font-narrow);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.32em;
  color: var(--sand);
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.8);
}
.brand-sail {
  color: var(--gold);
  font-size: 13px;
  transform: rotate(180deg);
  display: inline-block;
}

.vitals {
  width: 218px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 7px;
  background: linear-gradient(150deg, rgba(9, 32, 38, 0.82), rgba(5, 20, 25, 0.66));
  border: 1px solid var(--line);
  border-radius: 10px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
}

.vital {
  display: grid;
  grid-template-columns: 17px 1fr 28px;
  align-items: center;
  gap: 8px;
}
.vicon { font-size: 12px; color: var(--vital-color, #fff); text-align: center; }
.vbar {
  height: 7px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.12);
  overflow: hidden;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.45);
}
.vbar i {
  display: block;
  height: 100%;
  width: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--vital-color, #fff), color-mix(in srgb, var(--vital-color, #fff) 65%, white));
  transition: width 0.25s ease;
  box-shadow: 0 0 8px color-mix(in srgb, var(--vital-color, #fff) 55%, transparent);
}
.vval {
  font-family: var(--font-narrow);
  font-size: 11px;
  font-weight: 700;
  text-align: right;
  color: rgba(238, 244, 232, 0.75);
}
.vital[data-vital="health"] { --vital-color: #ff6b5a; }
.vital[data-vital="hunger"] { --vital-color: #f5a34a; }
.vital[data-vital="thirst"] { --vital-color: #58c8f3; }
.vital[data-vital="warmth"] { --vital-color: #ffd166; }
.vital[data-vital="stamina"] { --vital-color: #8fe36b; }

.quest-panel {
  width: 282px;
  padding: 11px 14px 12px;
  background: linear-gradient(160deg, rgba(9, 32, 38, 0.78), rgba(5, 20, 25, 0.6));
  border: 1px solid var(--line);
  border-left: 2px solid var(--gold);
  border-radius: 8px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
}
.panel-label {
  font-family: var(--font-narrow);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.28em;
  color: var(--teal);
  margin-bottom: 5px;
}
#questText { font-size: 12.5px; line-height: 1.42; color: #e7efe2; text-shadow: 0 1px 4px rgba(0, 0, 0, 0.5); }
.quest-extra { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 7px; }
.qchip {
  font-family: var(--font-narrow);
  font-size: 9px;
  letter-spacing: 0.04em;
  padding: 2px 6px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.09);
  color: var(--muted);
  white-space: nowrap;
}
.qchip.ok { color: #bff3a1; border-color: rgba(167, 227, 107, 0.35); background: rgba(100, 170, 70, 0.16); }
.qchip.no { color: #ffb7a5; border-color: rgba(255, 120, 90, 0.25); background: rgba(160, 60, 40, 0.13); }

.hud-right {
  position: absolute;
  top: calc(16px + env(safe-area-inset-top));
  right: calc(16px + env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 9px;
}
.minimap-wrap {
  position: relative;
  width: 156px;
  height: 156px;
  border-radius: 50%;
  background: rgba(4, 25, 31, 0.65);
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.45), inset 0 0 0 1px rgba(226, 240, 224, 0.18);
  overflow: visible;
}
#minimap { width: 100%; height: 100%; border-radius: 50%; }
.map-north {
  position: absolute;
  top: -7px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-narrow);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--sand);
  background: rgba(4, 25, 31, 0.95);
  padding: 1px 6px;
  border-radius: 9px;
  border: 1px solid var(--line);
}
.map-ring {
  position: absolute;
  inset: -5px;
  border-radius: 50%;
  pointer-events: none;
  background: repeating-conic-gradient(from 0deg, rgba(242, 215, 155, 0.62) 0deg 0.8deg, transparent 0.8deg 15deg);
  -webkit-mask: radial-gradient(circle, transparent 68%, #000 69%);
  mask: radial-gradient(circle, transparent 68%, #000 69%);
  opacity: 0.55;
}
.sky-info {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 5px 11px;
  border-radius: 20px;
  background: var(--panel);
  border: 1px solid var(--line);
  font-family: var(--font-narrow);
  font-size: 10px;
  letter-spacing: 0.09em;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
#clock { color: var(--sand); font-weight: 700; }
#weather { color: var(--muted); }
#weather.storm { color: #9fd3e8; }

.resources {
  display: flex;
  gap: 5px;
  padding: 6px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 9px;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.res {
  display: flex;
  align-items: center;
  gap: 3px;
  font-family: var(--font-narrow);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 5px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.055);
}
.res span { font-size: 12px; filter: saturate(0.9); }
.res b { color: #f2f5ea; min-width: 8px; text-align: center; }
.res.flare-res b { color: #ffd37a; }

.prompt {
  position: absolute;
  left: 50%;
  bottom: 17%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px 8px 9px;
  background: rgba(5, 22, 27, 0.88);
  border: 1px solid var(--line-strong);
  border-radius: 8px;
  box-shadow: 0 10px 32px rgba(0, 0, 0, 0.5);
  font-size: 13px;
  white-space: nowrap;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  pointer-events: none;
}
.prompt .key {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 28px;
  padding: 0 6px;
  border-radius: 5px;
  background: linear-gradient(180deg, #f5daa0, #d8ae62);
  color: #201408;
  font-family: var(--font-narrow);
  font-size: 12px;
  font-weight: 800;
  box-shadow: inset 0 1px 0 #fff3d0;
}
.prompt .key.mouse { font-size: 10px; }

.fishing-ui {
  position: absolute;
  left: 50%;
  bottom: 25%;
  transform: translateX(-50%);
  width: 250px;
  padding: 10px 14px 11px;
  text-align: center;
  background: rgba(5, 22, 27, 0.9);
  border: 1px solid var(--line-strong);
  border-radius: 9px;
  box-shadow: var(--shadow);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
#fishingLabel {
  font-family: var(--font-narrow);
  font-size: 11px;
  letter-spacing: 0.13em;
  font-weight: 800;
  color: var(--sand);
  margin-bottom: 7px;
  text-transform: uppercase;
}
#fishingLabel.bite { color: #ffd166; animation: bitePulse 0.3s ease infinite alternate; }
@keyframes bitePulse { from { transform: scale(1); } to { transform: scale(1.08); } }
.fishing-track {
  height: 6px;
  border-radius: 4px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.13);
}
#fishingFill {
  display: block;
  height: 100%;
  width: 0%;
  background: linear-gradient(90deg, #57d7c0, #f2d79b);
  border-radius: 4px;
}
#fishingFill.bite { background: linear-gradient(90deg, #ffb15c, #ff6f5e); animation: fillFlash 0.22s infinite alternate; }
@keyframes fillFlash { from { opacity: 0.7; } to { opacity: 1; } }
.fishing-note {
  margin-top: 6px;
  font-size: 10px;
  color: var(--muted);
  letter-spacing: 0.05em;
}
.fishing-note b { color: var(--sand); }

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 6px;
  height: 6px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.8);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.5), 0 0 9px rgba(255, 255, 255, 0.35);
  transition: background 0.15s ease, box-shadow 0.15s ease;
}
#crosshair.target { background: #ffd166; box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.55), 0 0 12px rgba(255, 190, 90, 0.7); }
#crosshair::after {
  content: "";
  position: absolute;
  inset: -8px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.0);
  transition: border-color 0.2s ease;
}
#crosshair.target::after { border-color: rgba(255, 209, 102, 0.35); }

#toasts {
  position: absolute;
  top: calc(18px + env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: min(440px, 84vw);
  pointer-events: none;
}
.toast {
  max-width: 100%;
  padding: 8px 15px;
  background: rgba(5, 22, 27, 0.9);
  border: 1px solid var(--line);
  border-left: 3px solid var(--gold);
  border-radius: 6px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  font-size: 12px;
  line-height: 1.35;
  color: #edf4e7;
  text-align: center;
  animation: toastIn 0.28s ease both;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.toast.good { border-left-color: var(--green); }
.toast.bad { border-left-color: var(--coral); }
.toast.flare { border-left-color: #ffb347; background: rgba(48, 27, 8, 0.92); color: #ffe3ad; }
.toast.out { animation: toastOut 0.35s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px) scale(0.97); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

.banner {
  position: absolute;
  top: 22%;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-narrow);
  font-size: clamp(22px, 4vw, 44px);
  font-weight: 800;
  letter-spacing: 0.24em;
  color: #d9ecf3;
  text-shadow: 0 2px 24px rgba(0, 0, 0, 0.75), 0 0 30px rgba(150, 200, 230, 0.25);
  opacity: 0;
  pointer-events: none;
  white-space: nowrap;
}
.banner.show { animation: bannerAnim 3.4s ease both; }
@keyframes bannerAnim {
  0% { opacity: 0; transform: translate(-50%, -12px) scale(0.97); letter-spacing: 0.4em; }
  15% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  78% { opacity: 1; }
  100% { opacity: 0; }
}

.hint {
  position: absolute;
  left: calc(18px + env(safe-area-inset-left));
  bottom: calc(14px + env(safe-area-inset-bottom));
  font-family: var(--font-narrow);
  font-size: 9.5px;
  letter-spacing: 0.04em;
  color: rgba(221, 235, 226, 0.55);
  text-shadow: 0 1px 6px rgba(0, 0, 0, 0.85);
  max-width: 60vw;
}

.sail-info {
  position: absolute;
  left: 50%;
  bottom: calc(14px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: baseline;
  gap: 7px;
  padding: 6px 14px;
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 18px;
  font-family: var(--font-narrow);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
