+    $('resumeBtn').addEventListener('click', () => this.togglePause(false));
+    $('pauseHelpBtn').addEventListener('click', () => this.openHelp('pause'));
+    $('restartBtn').addEventListener('click', () => window.location.reload());
+    $('muteBtn').addEventListener('click', () => {
