    const w = 0.055, hgt = 0.62, bend = 0.14;
    // base left/right
    positions.push(-dx*w, 0, -dz*w, dx*w, 0, dz*w);
    positions.push(-dx*w*0.35 + dz*bend, hgt, -dz*w*0.35 - dx*bend);
    positions.push(dx*w*0.35 + dz*bend, hgt, dz*w*0.35 - dx*bend);
    indices.push(vi, vi+1, vi+3, vi, vi+3, vi+2);
    vi += 4;
